from taf.cloud.cbam.schemas.schema_base import CbamSchema


class NoData(CbamSchema):
    def __init__(self, operation_id=None):
        self.operation_id = operation_id

    @classmethod
    def from_response_dict(cls, resp_dict):
        try:
            return cls(operation_id=resp_dict.get('operationId', None))
        except (AttributeError):
            return cls()

    def as_dict(self):
        attributes = {'operationId': self.operation_id}

        attributes = {k: v for k, v in attributes.items() if v}

        return attributes
